// @ts-nocheck
// ===== ทดสอบอ่าน DI1–DI4 (ยังไม่ต้องมี Relay ใช้สายไฟจั๊มเอา) =====
// สถานะใต้โหนดแสดง DI1–DI4 สด ● = ติด ○ = ดับ · ส่งออก debug เฉพาะตอนค่าเปลี่ยน
function truthy(v) {
    if (v === null || v === undefined) return null;
    if (typeof v === "boolean") return v;
    if (typeof v === "number") return v !== 0;
    const s = String(v).trim().toLowerCase();
    if (["1", "true", "on", "high"].includes(s)) return true;
    if (["0", "false", "off", "low"].includes(s)) return false;
    return null;
}
function pick(m, n) {
    const p = m.payload; let v;
    if (Array.isArray(p)) v = p[n - 1];
    else if (p && typeof p === "object") {
        for (const k of ["DI" + n, "di" + n, "Di" + n, "DI_" + n, "di_" + n, "input" + n, "IN" + n, String(n)])
            if (p[k] !== undefined) { v = p[k]; break; }
        if (v && typeof v === "object") v = v.value ?? v.state ?? v.status;
    }
    else if (typeof p === "number" && Number.isInteger(p)) v = (p >> (n - 1)) & 1;
    if (v === undefined && m["DI" + n] !== undefined) v = m["DI" + n];
    return truthy(v);
}
const vals = [1, 2, 3, 4].map(n => pick(msg, n));
if (vals.every(v => v === null)) {
    node.status({ fill: "red", shape: "ring", text: "อ่านรูปแบบค่าไม่ออก – เปิด debug 'ค่า DI ดิบ' แล้วส่งให้ดู" });
    return null;
}
const sym = v => v === null ? "?" : v ? "●" : "○";
const txt = vals.map((v, k) => "DI" + (k + 1) + sym(v)).join("  ");
node.status({ fill: vals.some(v => v) ? "green" : "grey", shape: "dot", text: txt });
const key = vals.join(",");
if (context.get("last") === key) return null;      // ส่งเฉพาะตอนเปลี่ยน
context.set("last", key);
msg.payload = { time: new Date().toLocaleTimeString("th-TH"), DI1: vals[0], DI2: vals[1], DI3: vals[2], DI4: vals[3], text: txt };
return msg;
